.global-image {
    position: relative;
    overflow: hidden;
    border-radius: 40px;
}
.global-image:before {
    content: "";
    z-index: 1;
    position: absolute;
    background: var(--theme-color);
    display: block;
    width: 100%;
    height: 100%;
    border-radius: 40px;
    -webkit-transform-origin: 100% 50%;
    -ms-transform-origin: 100% 50%;
    transform-origin: 100% 50%;
    -webkit-transform: scaleX(0) translateX(0);
    -ms-transform: scaleX(0) translateX(0);
    transform: scaleX(0) translateX(0);
    -webkit-animation: 1s overlay ease-in-out forwards;
    animation: 1s overlay ease-in-out forwards;
}
.global-image img {
    width: 100%;
    height: 100%;
    border-radius: 40px;
    -webkit-animation: 1s 0.5s loaded cubic-bezier(0.49, 0, 0.5, 1) forwards;
    animation: 1s 0.5s loaded cubic-bezier(0.49, 0, 0.5, 1) forwards;
    -webkit-transform: scale(0.8);
    -ms-transform: scale(0.8);
    transform: scale(0.8);
    opacity: 0;
    display: block;
}
@-webkit-keyframes loaded {
    from {
        -webkit-transform: scale(0.8);
        transform: scale(0.8);
        opacity: 0;
    }
    to {
        -webkit-transform: scale(1);
        transform: scale(1);
        opacity: 1;
    }
}
@keyframes loaded {
    from {
        -webkit-transform: scale(0.8);
        transform: scale(0.8);
        opacity: 0;
    }
    to {
        -webkit-transform: scale(1);
        transform: scale(1);
        opacity: 1;
    }
}
@-webkit-keyframes overlay {
    0% {
        -webkit-transform: scaleX(0);
        transform: scaleX(0);
    }
    55% {
        -webkit-transform: scaleX(1);
        transform: scaleX(1);
    }
    100% {
        -webkit-transform: translateX(-100%);
        transform: translateX(-100%);
    }
}
@keyframes overlay {
    0% {
        -webkit-transform: scaleX(0);
        transform: scaleX(0);
    }
    55% {
        -webkit-transform: scaleX(1);
        transform: scaleX(1);
