    opacity: 0
}

.fade-appear,.fade-enter,.fade-leave {
    -webkit-animation-timing-function: linear;
    animation-timing-function: linear
}

@-webkit-keyframes antFadeIn {
    0% {
        opacity: 0
    }

    to {
        opacity: 1
    }
}

@keyframes antFadeIn {
    0% {
        opacity: 0
    }

    to {
        opacity: 1
    }
}

@-webkit-keyframes antFadeOut {
    0% {
        opacity: 1
    }

    to {
        opacity: 0
    }
}

