.booking-drawer {
  font-family: "Poppins", sans-serif;
}

.booking-drawer .drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
  z-index: 999;
}

.booking-drawer .drawer-content {
  position: fixed;
  top: 0;
  right: -100%;
  width: 80%;
  max-width: 1000px;
  height: 100%;
  background: #fff;
  overflow-y: auto;
  transition: all 0.4s ease;
  z-index: 1000;
  padding: 25px;
  box-shadow: -3px 0 8px rgba(0, 0, 0, 0.1);
}

.booking-drawer.active .drawer-overlay {
  opacity: 1;
  visibility: visible;
}

.booking-drawer.active .drawer-content {
  right: 0;
}

/* Close Button */
.booking-drawer .close-btn {
  background: none;
  border: none;
  font-size: 28px;
  position: absolute;
  top: 15px;
  right: 20px;
  cursor: pointer;
}

/* Layout */
.booking-drawer .booking-container {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 2rem;
  margin-top: 40px;
}

.booking-drawer .form-section {
  margin-bottom: 1.5rem;
}

.booking-drawer .form-section h3 {
    margin-bottom: 10px;
    color: var(--theme-color);
    font-weight: 600;
    font-size: 20px;
}

.booking-drawer label {
    display: flex;
    align-items: center;
    gap: 7px;
    font-size: 14px;
    margin-bottom: 5px;
    color: #444;
    font-weight: 600;
}

.booking-drawer input,
.booking-drawer select,
.booking-drawer textarea {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #ccc;
  border-radius: 4px;
  font-size: 14px;
    height: 35px;
}

.upi-methods {
    display: flex;
    align-items: center;
    gap: 10px;
}

.upi-methods img {
    width: 50px;
}

.booking-drawer input[type="radio"] {
    visibility: visible;
    opacity: 1;
    display: block;
    height: 15px;
    width: 15px;
}

.booking-drawer textarea {
  resize: none;
}

.booking-drawer .input-group {
      display: flex
;
    gap: 0;
    flex-direction: row;
    flex-wrap: nowrap;
}

.booking-drawer .grid-2,
.booking-drawer .grid-3,
.booking-drawer .grid-4 {
  display: grid;
  gap: 1rem;
}

.booking-drawer .grid-2 { grid-template-columns: repeat(2, 1fr); }
.booking-drawer .grid-3 { grid-template-columns: repeat(3, 1fr); }
.booking-drawer .grid-4 { grid-template-columns: repeat(4, 1fr); }

.booking-drawer .checkboxes,
.booking-drawer .payment-methods {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
  margin-top: 10px;
}

.booking-drawer .side-panel {
  border-left: 1px solid #ddd;
  padding-left: 20px;
}

.booking-drawer .side-panel h4 {
    font-size: 20px;
  color: var(--theme-color);
  margin-bottom: 10px;
}

.service-details {
        padding-bottom: 20px;
}

.booking-drawer .service-details p,
.booking-drawer .fare-details p {
  font-size: 14px;
  margin: 4px 0;
}

.booking-drawer textarea {
    min-height: 50px;
}

select#boarding-point {
    padding: 0 10px;
    padding-right: 30px;
    height: 35px;
    border-radius: 0;
}
.landmark-content {
    display: flex;
    align-items: center;
}
.booking-drawer .terms {
    font-size: 14px;
}

@media (max-width: 991px) {
  .booking-drawer .booking-container {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .booking-drawer .side-panel {
    border-left: none;
    border-top: 1px solid #ddd;
    padding-left: 0;
    margin-top: 20px;
    padding-top: 20px;
  }
}

@media(max-width: 543px) {
    .booking-drawer .drawer-content {
        width: 95%;
        padding: 25px 15px;
    }
    .booking-drawer .booking-container {
        margin-top: 0px;
    }
    .booking-drawer .grid-2, .booking-drawer .grid-3, .booking-drawer .grid-4 {
        gap: 0.5rem;
    }
    .booking-drawer .grid-2 {
        grid-template-columns: repeat(1, 1fr);
    }
    .booking-drawer .grid-4 {
        grid-template-columns: repeat(2, 1fr);
    }
}
